import os
import torch


class Config:
    """
    Global configuration for the Hybrid Stacking Strategy (XGBoost + ResNet).
    """

    # =========================================================================
    # Directories & Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_3"
    SUBMISSION_DIR = "./submission"

    # Raw Data Paths (Generated by metadata script)
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Sample Submission
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Output Submission Path
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Processed Data Cache Paths (Parquet format)
    TRAIN_PROCESSED_PATH = os.path.join(WORKING_DIR, "train_processed.parquet")
    VAL_PROCESSED_PATH = os.path.join(WORKING_DIR, "val_processed.parquet")
    TEST_PROCESSED_PATH = os.path.join(WORKING_DIR, "test_processed.parquet")

    # =========================================================================
    # Global Settings
    # =========================================================================
    SEED = 42
    N_FOLDS = 5
    TARGET_COL = "Cover_Type"
    ID_COL = "Id"

    # Forest Cover Type has 7 classes (1-7).
    # We assume preprocessing maps these to 0-6 for training.
    NUM_CLASSES = 7

    # =========================================================================
    # XGBoost Hyperparameters (Level 0)
    # =========================================================================
    # Optimized settings: max_depth=10, eta=0.05, gpu_hist
    XGB_PARAMS = {
        "objective": "multi:softprob",
        "num_class": NUM_CLASSES,
        "tree_method": "hist",
        "device": "cuda",
        "max_depth": 10,
        "learning_rate": 0.05,
        "subsample": 0.85,
        "colsample_bytree": 0.85,
        "gamma": 0.1,
        "lambda": 1.0,
        "alpha": 0.0,
        "n_jobs": 12,
        "verbosity": 0,
        "seed": SEED,
        "eval_metric": "mlogloss",
    }

    # XGBoost Training Control
    XGB_FIT_PARAMS = {
        "num_boost_round": 5000,
        "early_stopping_rounds": 50,
        "verbose_eval": 100,
    }

    # =========================================================================
    # Neural Network Hyperparameters (Level 0 - ResNet)
    # =========================================================================
    NN_PARAMS = {
        # Architecture
        "hidden_dims": [256, 128, 64],  # Dimensions for residual blocks
        "dropout_rate": 0.2,
        "use_batch_norm": True,
        # Training
        "learning_rate": 1e-3,
        "weight_decay": 1e-4,
        "batch_size": 2048,
        "epochs": 50,
        "patience": 7,  # Early stopping patience
        "device": "cuda" if torch.cuda.is_available() else "cpu",
        "num_workers": 4,
    }

    # =========================================================================
    # Meta-Learner Hyperparameters (Level 1 - Logistic Regression)
    # =========================================================================
    META_PARAMS = {
        "C": 0.1,
        "penalty": "l2",
        "solver": "lbfgs",
        "max_iter": 1000,
        "random_state": SEED,
        "n_jobs": -1,
    }
